const payload = $input.first().json.body || $input.first().json;

let phone = (payload.phone || '').replace(/[^0-9]/g, '');
if (phone.startsWith('0')) {
  phone = '92' + phone.substring(1);
}

const customerName = payload.customerName || 'Janab';
const productTitle = payload.productTitle || 'Luxury Watch';
const variant = payload.variant || 'Standard';
const price = payload.price || 1999;

// WhatsApp message text in high-converting, polite Roman Urdu
const messageText = `Assalam-o-Alaikum ${customerName}! 🌟\n\nMain Muhammad Mubashar baat kar raha hoon MUBAR Store (mubarstore.com) Lahore se.\n\nAap ne thori der pehle humari website par *${productTitle}* (${variant}) pasand ki thi. Kya aap ka order place karte waqt koi masla paish aaya?\n\nBhai humari policy 100% customer-first hai:\n✅ *Cash on Delivery (COD)* poore Pakistan mein available hai\n✅ *100% Free Express Delivery* (Zero courier charges)\n✅ *100% Open Parcel Check Guarantee* — Rider aap ke samne pehle parcel khole ga, aap tasalli se check karein, pasand aane par payment karein! Zero risk.\n\nAgar aap order book karwana chahte hain to sirf apna shehar aur address is WhatsApp par bhej dein, hum foran priority dispatch karwa denge.\n\nShukriya!\nFounder, MUBAR Store (+92 308 4453846)`.trim();

return [{
  json: {
    phone,
    customerName,
    productTitle,
    variant,
    price,
    messageText
  }
}];
